      {"id": "enmu-rnbsn", "institution": "enmu", "credential": "rnbsn", "name": "Bachelor of Science in Nursing (BSN) Completion Program", "length": "8-week courses; full-time students can finish in 4 semesters (about 16 months) once general education is complete; 32 nursing credits within a 120-credit degree (30 of the last 40 credits at ENMU)", "format": "100% online", "prerequisites": [{"course": "Introduction to Statistics (required for the degree)", "code": "MATH 1350", "min_grade": "C"}], "admission": {"entrance_exam": null, "selection": "Rolling admission; fall, spring and summer starts (five intakes a year)", "gpa": null, "deadline": "No set deadline", "notes": "Active U.S. RN license (or NCLEX-eligible and passed within the first semester after admission); U.S. residence (military exception); C or higher in all nursing and prerequisite science courses; separate ENMU and BSN applications; no application fee."}, "cost": {"amount": 294.75, "basis": "Per credit hour, New Mexico resident tuition ($174.75) + fees ($120), 2026-27 (non-resident $377.25). ENMU's catalog also lists an online course fee of $17/credit not included here — check with the school.", "year": "2026-27"}, "nclex_pass_rate": {"basis": "Not applicable — RN-to-BSN completion program; students are already licensed", "by_campus": null, "source_url": null}, "accreditation": "ACEN (continuing accreditation since 1995; next visit spring 2029)", "source_url": "https://www.enmu.edu/academics/degrees-programs/undergraduate-degree/bachelor/bachelor-of-science-in-nursing", "last_verified": "2026-11-17", "academic_year": "2026-27", "notes": "Handbook (2024-2027): https://www.enmu.edu/images/academics/liberal-arts-sciences/health-human-services/bsn-student-handbook.pdf. Tuition: https://www.enmu.edu/admission/tuition-fees. ENMU states the program does not give an RN license and refers pre-licensure students to ENMU-Roswell. ENMU's MSN is a nurse-educator emphasis only (out of scope).", "open_entry": true},
      {"id": "mesalands-adn", "institution": "mesalands", "credential": "adn", "name": "Associate of Applied Science in Nursing", "length": "Advertised as becoming an RN 'within 2 years'; cost basis uses 78 credits including prerequisites", "format": "In person, Tucumcari (simulation lab and clinical rotations at regional hospitals)", "prerequisites": [], "admission": {"entrance_exam": null, "selection": null, "gpa": null, "deadline": "Applications accepted 'until the end of May' (year not stated)", "notes": "College application plus a separate nursing program application emailed to the program (shannonf@mesalands.edu). Prerequisite courses, GPA and entrance exam not confirmed: the nursing page is rendered by JavaScript and could not be read in full."}, "cost": {"amount": null, "basis": "Nursing page estimates (based on 78 credits incl. prerequisites) conflict: one section gives $13,385.31 (NM resident) / $17,519.31 (non-resident), the FAQ gives $10,929.50 / $15,063.50 — check with the school. Tuition page: $63/credit NM resident, $116 non-resident.", "year": null}, "nclex_pass_rate": {"basis": "New program: no graduates appear in the New Mexico Board of Nursing's NCLEX-RN results yet.", "by_campus": null, "source_url": null}, "accreditation": "ACEN candidate for initial accreditation (candidacy effective June 27, 2025, expires June 27, 2027); a July 27, 2026 public notice announced an ACEN initial-accreditation site visit for the AAS in Nursing", "source_url": "https://www.mesalands.edu/page/nursing/", "last_verified": "2026-11-17", "academic_year": null, "notes": "New program: NM BON Full Approval May 1, 2025 – June 30, 2027 per the nursing page. College reports 100% NCLEX pass for its December 2024 graduates. Facts gathered from search-indexed text of mesalands.edu pages because the live pages render via JavaScript; many fields unconfirmed — check with the school."},
      {"id": "nmjc-adn", "institution": "nmjc", "credential": "adn", "name": "Associate of Applied Science in Nursing", "length": "4 semesters (Levels 1-4) after 21 credits of prerequisites; 70 credits total", "format": "In person/hybrid, Hobbs (classroom, lab, simulation; clinical sites in New Mexico and Texas)", "prerequisites": [{"course": "Basic science: one of Microbiology (recommended), General Biology I/II, Cellular & Molecular Biology, Principles of Biology, Intro to Chemistry, General Chemistry I/II", "code": "BIOL 2310C (recommended) or BIOL 1101C/1111C/2120C/2610C, CHEM 1120C/1215C/1225C", "min_grade": "C"}, {"course": "Human Anatomy & Physiology I", "code": "BIOL 2210C", "min_grade": "C"}, {"course": "Human Anatomy & Physiology II", "code": "BIOL 2225C", "min_grade": "C"}, {"course": "Composition I", "code": "ENGL 1110", "min_grade": "C"}, {"course": "Introduction to Psychology", "code": "PSYC 1110", "min_grade": "C"}, {"course": "Developmental Psychology", "code": "PSYC 2120", "min_grade": "C"}], "admission": {"entrance_exam": "ATI TEAS: adjusted individual total 58.7% minimum AND cut scores Reading 72.8%, Math 68.8%, Science 58%, English 66.8% (max 3 attempts/year, 30 days apart)", "selection": "Selective, holistic ranking: TEAS scores, prerequisite GPA, overall GPA, interview with director/committee, academic history, application packet/letter of intent; healthcare experience (CNA, CMA, EMT) and extra courses (Medical Terminology, Microbiology, Nutrition with B or higher) considered", "gpa": "2.75 cumulative in the BIOL/CHEM course, ENGL 1110, PSYC 1110, PSYC 2120 and BIOL 2210C; 2.0 overall", "deadline": "May 20, 5:00 pm (next Monday if a weekend) for fall admission; applications accepted May 1-20", "notes": "Prerequisites within 5 years (director may allow exceptions). Letter of intent, resume, NMJC physical form, transcripts; TOEFL iBT 84 (speaking 26) for international students. Annual fingerprinting/background check, random drug screens, health insurance. Mandatory boot camp in July/August."}, "cost": {"amount": 40, "basis": "Tuition per credit hour, NMJC in-district resident, effective Fall 2026 (max $480 for 12+ credits), plus $18/credit general usage fee. Out-of-district NM $60, out-of-state $75. ATI package $4,201 over 4 semesters; Level 1 books about $2,500.", "year": "2026-27"}, "nclex_pass_rate": {"basis": "First-time NCLEX-RN pass rate, New Mexico Board of Nursing \"End of Year 2025\" NCLEX table (calendar year); 29 tested in 2025", "by_campus": {"All campuses": [{"year": 2025, "rate": 0.8621, "tested": 29}, {"year": 2024, "rate": 0.963, "tested": 27}, {"year": 2023, "rate": 1.0, "tested": 14}]}, "source_url": "https://files.bon.nm.gov/WebDocs/NCLEX%20Pass%20Rates.pdf"}, "accreditation": "ACEN (continuing accreditation)", "source_url": "https://www.nmjc.edu/program/nursing/documents/F2026%20ADN%20ADMISSION%20REQUIREMENTS.pdf", "last_verified": "2026-11-17", "academic_year": "2026-27", "notes": "Program page: https://www.nmjc.edu/program/nursing/ ; degree plan: https://www.nmjc.edu/program/nursing/documents/FA26_AAS_Nursing_Degree_Plan.pdf ; cost estimate: https://www.nmjc.edu/program/nursing/documents/26FallNMJC_Estimate_Costs_Program_Tech.pdf. NM BON Full Approval. NMJC's current materials no longer mention NMNEC or a UNM BSN option (courses use NMJC's own NURS numbers); an NMNEC/UNM BSN partnership appears only in a 2018-19 handbook. NMJC also offers a separate Practical Nursing (LPN) certificate (out of scope)."},
      {"id": "nmjc-adn-lpn-bridge", "institution": "nmjc", "credential": "adn", "bridge_from": "lpn", "name": "AAS in Nursing — LPN to RN Accelerated (Transition) Pathway", "length": "Summer transition semester (10 weeks) + 2 semesters (Levels 3 and 4); 70 credits incl. 13 credits for prior learning", "format": "Hybrid/online didactic via Canvas with mandatory 5-day on-campus intensives (summer and start of Level 4); clinicals in person", "prerequisites": [{"course": "Basic science: one of Microbiology (recommended), General Biology I/II, Cellular & Molecular Biology, Principles of Biology, Intro to Chemistry, General Chemistry I/II", "code": "BIOL 2310C (recommended) or BIOL 1101C/1111C/2120C/2610C, CHEM 1120C/1215C/1225C", "min_grade": "C"}, {"course": "Human Anatomy & Physiology I", "code": "BIOL 2210C", "min_grade": "C"}, {"course": "Human Anatomy & Physiology II", "code": "BIOL 2225C", "min_grade": "C"}, {"course": "Composition I", "code": "ENGL 1110", "min_grade": "C"}, {"course": "Introduction to Psychology", "code": "PSYC 1110", "min_grade": "C"}, {"course": "Developmental Psychology", "code": "PSYC 2120", "min_grade": "C"}], "admission": {"entrance_exam": "ATI TEAS with minimum overall and category cut scores", "selection": "Selective, competitive, limited to 12 seats; interview", "gpa": "2.75 cumulative in prerequisites; 2.0 overall; LPN program GPA 2.0+", "deadline": "March 20 (or following Monday), 5:00 pm, for summer 2027 admission", "notes": "Requires a current, unencumbered LPN/LVN license in New Mexico or Texas, completion of an accredited LPN/LVN program, 2 calendar years as an LPN/LVN and 2,000 documented hours in the last 3 years, plus a supervisor letter. 5-year prerequisite rule waived for LPNs with 2,000 hours in the past 2 years. Degree plan also lists a not-yet-numbered paramedic transition course."}, "cost": {"amount": 40, "basis": "Tuition per credit hour, NMJC in-district resident, effective Fall 2026 (max $480 for 12+ credits), plus $18/credit general usage fee; ATI $1,050.25 per semester; books about $2,800", "year": "2026-27"}, "nclex_pass_rate": {"basis": "First-time NCLEX-RN pass rate, New Mexico Board of Nursing \"End of Year 2025\" NCLEX table (calendar year); 29 tested in 2025", "by_campus": {"All campuses": [{"year": 2025, "rate": 0.8621, "tested": 29}, {"year": 2024, "rate": 0.963, "tested": 27}, {"year": 2023, "rate": 1.0, "tested": 14}]}, "source_url": "https://files.bon.nm.gov/WebDocs/NCLEX%20Pass%20Rates.pdf"}, "accreditation": "ACEN (NMJC ADN program accreditation)", "source_url": "https://www.nmjc.edu/program/nursing/documents/Su27NMJC%20AAS%20in%20Nursing%20LPN%20to%20RN%20Transition%20Option%20Description%20Application%20Criteria%20Degree%20Plan%20LPN%20to%20RN%20.pdf", "last_verified": "2026-11-17", "academic_year": "2026-27", "notes": "Listed on the program page as a '*New Program'. Cost sheet: https://www.nmjc.edu/program/nursing/documents/NMJC_Estimate_Costs_Program_Fall%202026.pdf. The program page lists LPN-to-RN applications March 1-20."},
      {"id": "senmc-adn", "institution": "senmc", "credential": "adn", "name": "Associate Degree in Nursing (AAS), PN/ADN career ladder", "length": "4 semesters of nursing after 17 credits of prerequisites; 74 credits total (PN certificate exit after 2 semesters + a summer course)", "format": "In person, Carlsbad (clinical sites vary, not always in Carlsbad)", "prerequisites": [{"course": "Human Anatomy and Physiology I", "code": "BIOL 2210", "min_grade": "C"}, {"course": "Introduction to Chemistry", "code": "CHEM 1120G", "min_grade": "C"}, {"course": "Nursing Assistant Theory and Lab (or current CNA certificate)", "code": "NUAS 1110C", "min_grade": "C"}, {"course": "Medical Terminology", "code": "HLSC 1510", "min_grade": "C"}], "admission": {"entrance_exam": "HESI A2: composite 75%+ and 60%+ on each of Math, Reading Comprehension, Vocabulary & General Knowledge, Grammar, Anatomy & Physiology (2 attempts per 12 months; valid one year)", "selection": "Competitive point system: HESI composite + grade points x credits for prerequisite/curriculum courses + 5 points for 15+ credits at SENMC", "gpa": "2.75 nursing-related GPA", "deadline": "Fall 2026 packet: 5:00 pm on the third Monday of May (the pre-nursing advising guide says last Monday / second Monday of May — check with the school)", "notes": "Advising appointment with the program director required. BIOL 2210, BIOL 2225 and CHEM 1120G within 5 years. NUAS 1110C waived with current CNA certification. BIOL 2225 and PSYC 1110G before semester 2; ENGL 1110G and CEPY 1120G before year 2. Licensed LPNs may be admitted with advanced standing through the same selection process (credit for first-year nursing courses; NACE exams if PN coursework is over 3 years old)."}, "cost": {"amount": 41, "basis": "Tuition per credit hour, in-district (Carlsbad) resident, 2026-27, plus $13/credit fees (out-of-district NM $54, non-resident $221; flat rate for 12-18 credits). Handbook total program estimate: $7,000-$12,000 (tuition $3,000-$4,500 for 57-74 credits plus books, fees, clinical travel).", "year": "2026-27"}, "nclex_pass_rate": {"basis": "First-time NCLEX-RN pass rate, New Mexico Board of Nursing \"End of Year 2025\" NCLEX table (calendar year)", "by_campus": {"All campuses": [{"year": 2025, "rate": 0.9286}, {"year": 2024, "rate": 1.0, "tested": 13}, {"year": 2023, "rate": 1.0, "tested": 10}]}, "source_url": "https://files.bon.nm.gov/WebDocs/NCLEX%20Pass%20Rates.pdf"}, "accreditation": "ACEN (continuing accreditation; accredited since 1990)", "source_url": "https://senmc.edu/documents/nursing-documents/2026-2027-senmc-handbook.pdf", "last_verified": "2026-11-17", "academic_year": "2026-27", "notes": "Formerly NMSU-Carlsbad (independent since July 1, 2021). NM BON Full Approval April 1, 2020, renewal due before March 31, 2028. Program page: https://senmc.edu/academic-departments/nursing.html ; application packet: https://senmc.edu/documents/nursing-documents/admission-application-packet.pdf ; tuition: https://www.senmc.edu/business-office/tuition-fees.html. The 2025 pre-nursing advising guide lists older course codes (NA 101, HIT 150/NURS 150); the 2026-27 handbook was used."},
      {"id": "gcu-nm-absn", "institution": "gcu-nm", "credential": "absn", "name": "Bachelor of Science in Nursing: Pre-Licensure, Accelerated (ABSN), Albuquerque", "length": "As little as 16 months (for eligible students); 123-credit degree; 15-week terms", "format": "Hybrid: online coursework + in-person skills labs and simulation at the Albuquerque learning site (6200 Jefferson St. NE, Suite 300) + clinical rotations at Albuquerque-area sites", "prerequisites": [{"course": "Human Anatomy and Physiology II + Lab", "code": "BIO-202 / BIO-202L", "min_grade": "C"}, {"course": "Microbiology + Lab", "code": "BIO-205 / BIO-205L", "min_grade": "C"}, {"course": "Applied Nutrition", "code": "BIO-319", "min_grade": "C"}, {"course": "Applied Pathophysiology", "code": "BIO-322", "min_grade": "C"}, {"course": "Introduction to General, Organic and Biochemistry + Lab", "code": "CHM-101 / CHM-101L", "min_grade": "C"}, {"course": "Lifespan Development", "code": "PSY-357", "min_grade": "C"}], "admission": {"entrance_exam": "HESI A2: 80% in Math, Reading Comprehension, Grammar and Vocabulary; 75% in Anatomy & Physiology", "selection": "Pre-admission interview; university counselor process", "gpa": "Cumulative programmatic GPA 3.0+; 3.25+ in ABSN prerequisite courses", "deadline": "Three start dates per year (dates not published)", "notes": "Secondary applicants must transfer at least 60 of 123 credits or hold a bachelor's degree with the 9 prerequisite courses/labs and 10 general education courses; 'Direct Entry' applicants can complete the 60 credits at GCU first. Prerequisites must be within the past 7 years. Background check. No prior healthcare experience required."}, "cost": {"amount": 850, "basis": "Campus tuition per credit (GCU's general ABSN page; prerequisite courses $425 per credit). Not stated specifically for Albuquerque and no year given.", "year": null}, "nclex_pass_rate": {"basis": "New program: no graduates appear in the New Mexico Board of Nursing's NCLEX-RN results yet.", "by_campus": null, "source_url": null}, "accreditation": "CCNE (GCU states its pre-licensure BSN is CCNE-accredited; its accreditation page does not mention the Albuquerque site specifically)", "source_url": "https://www.gcu.edu/degree-programs/absn-accelerated-bsn/new-mexico/albuquerque", "last_verified": "2026-11-17", "academic_year": "2026-27", "notes": "Only program offered at the Albuquerque site. GCU says the NM Board of Nursing has given the ABSN 'initial approval' (https://www.gcu.edu/academics/accreditation/state-licensure-program-approvals). Admission/tuition details from https://www.gcu.edu/degree-programs/absn-accelerated-bsn and https://www.gcu.edu/degree-programs/absn-accelerated-bsn/prerequisites. Ownership caveat: GCU is Arizona-based and describes itself as a private nonprofit, but its nonprofit status has been contested (the U.S. Department of Education treated it as for-profit for federal aid purposes; litigated) — check current status."}
